const API_URL=window.location.hostname.includes("localhost")?"http://localhost:3000/api":"https://rp-world-backend.onrender.com/api";async function getUserInfo(username){try{const response=await fetch(`${API_URL}/user/${username}`);const data=await response.json();if(data.success){return data.user}return null}catch(error){console.error("Fehler beim Abrufen der Benutzerinfo:",error);return null}}async function getAllUsers(adminUsername){try{const response=await fetch(`${API_URL}/users/${adminUsername}`);const data=await response.json();if(data.success){return data.users}return[]}catch(error){console.error("Fehler beim Abrufen der Benutzerliste:",error);return[]}}async function changePassword(username,oldPassword,newPassword){try{const response=await fetch(`${API_URL}/change-password`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({username:username,oldPassword:oldPassword,newPassword:newPassword})});const data=await response.json();return data.success}catch(error){console.error("Fehler beim Ändern des Passworts:",error);return false}}async function addUser(adminUsername,newUsername,newPassword,canCreateUsers){try{const response=await fetch(`${API_URL}/create-user`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({adminUsername:adminUsername,newUsername:newUsername,newPassword:newPassword,canCreateUsers:canCreateUsers})});const data=await response.json();return data.success}catch(error){console.error("Fehler beim Erstellen des Benutzers:",error);return false}}async function deleteUser(adminUsername,targetUsername){try{const response=await fetch(`${API_URL}/delete-user`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({adminUsername:adminUsername,targetUsername:targetUsername})});const data=await response.json();return data.success}catch(error){console.error("Fehler beim Löschen des Benutzers:",error);return false}}document.addEventListener("DOMContentLoaded",async function(){const currentUser=localStorage.getItem("currentAdminUser");if(!currentUser){alert("Du musst angemeldet sein um auf diese Seite zuzugreifen!");window.location.href="Untitled-1.html";return}let userInfo=await getUserInfo(currentUser);if(!userInfo){alert("Benutzer nicht gefunden!");window.location.href="Untitled-1.html";return}document.getElementById("welcomeUsername").textContent=currentUser;document.getElementById("currentUserDisplay").textContent=currentUser;if(userInfo.canCreateUsers){document.getElementById("userManagementBox").style.display="block"}const changePasswordModal=document.getElementById("changePasswordModal");const userManagementModal=document.getElementById("userManagementModal");const changePasswordBtn=document.getElementById("changePasswordBtn");const manageUsersBtn=document.getElementById("manageUsersBtn");const closePasswordModal=document.getElementById("closePasswordModal");const closeUserManagementModal=document.getElementById("closeUserManagementModal");const changePasswordForm=document.getElementById("changePasswordForm");const addUserForm=document.getElementById("addUserForm");const logoutBtn=document.getElementById("logoutBtn");if(changePasswordBtn){changePasswordBtn.addEventListener("click",function(){changePasswordModal.classList.add("show")})}if(closePasswordModal){closePasswordModal.addEventListener("click",function(){changePasswordModal.classList.remove("show");changePasswordForm.reset()})}if(changePasswordForm){changePasswordForm.addEventListener("submit",async function(e){e.preventDefault();const currentPassword=document.getElementById("currentPassword").value;const newPassword=document.getElementById("newPassword").value;const confirmPassword=document.getElementById("confirmPassword").value;if(newPassword.length<4){alert("Das neue Passwort muss mindestens 4 Zeichen lang sein!");return}if(newPassword!==confirmPassword){alert("Passwörter stimmen nicht überein!");return}const success=await changePassword(currentUser,currentPassword,newPassword);if(success){alert("Passwort erfolgreich geändert! Die Änderung ist sofort auf allen Geräten verfügbar.");changePasswordModal.classList.remove("show");changePasswordForm.reset()}else{alert("Fehler beim Ändern des Passworts! Aktuelles Passwort ist möglicherweise falsch.");changePasswordForm.reset()}})}window.addEventListener("click",function(event){if(event.target===changePasswordModal){changePasswordModal.classList.remove("show");changePasswordForm.reset()}if(event.target===userManagementModal){userManagementModal.classList.remove("show");addUserForm.reset()}});if(manageUsersBtn){manageUsersBtn.addEventListener("click",function(){userManagementModal.classList.add("show");renderUsersList()})}if(closeUserManagementModal){closeUserManagementModal.addEventListener("click",function(){userManagementModal.classList.remove("show");addUserForm.reset()})}async function renderUsersList(){const usersList=document.getElementById("usersList");const users=await getAllUsers(currentUser);usersList.innerHTML="";if(users.length===0){usersList.innerHTML='<p style="text-align: center; color: #999;">Keine Benutzer gefunden</p>';return}users.forEach(userData=>{const username=userData.username;const userItem=document.createElement("div");userItem.className="user-item";const userInfo=document.createElement("div");userInfo.className="user-info";const createdAt=new Date(userData.createdAt).toLocaleDateString("de-DE");userInfo.innerHTML=`\n        <div class="user-name">${username}</div>\n        <div class="user-badge">${userData.canCreateUsers?"👑 Super Admin":"👤 Admin"}</div>\n        <div style="font-size: 0.85rem; color: #999; margin-top: 0.3rem;">Erstellt: ${createdAt}</div>\n      `;const userActions=document.createElement("div");userActions.className="user-actions";if(username!=="carlos"&&username!==currentUser){const deleteBtn=document.createElement("button");deleteBtn.className="delete-btn";deleteBtn.textContent="Löschen";deleteBtn.addEventListener("click",async function(){if(confirm(`Möchtest du den Benutzer "${username}" wirklich löschen?`)){const success=await deleteUser(currentUser,username);if(success){alert("Benutzer erfolgreich gelöscht! Die Änderung ist sofort auf allen Geräten verfügbar.");renderUsersList()}else{alert("Fehler beim Löschen des Benutzers!")}}});userActions.appendChild(deleteBtn)}else if(username==="carlos"){const badge=document.createElement("span");badge.style.color="#999";badge.style.fontSize="0.85rem";badge.textContent="(nicht löschbar)";userActions.appendChild(badge)}else if(username===currentUser){const badge=document.createElement("span");badge.style.color="#999";badge.style.fontSize="0.85rem";badge.textContent="(du bist dieser Benutzer)";userActions.appendChild(badge)}userItem.appendChild(userInfo);userItem.appendChild(userActions);usersList.appendChild(userItem)})}if(addUserForm){addUserForm.addEventListener("submit",async function(e){e.preventDefault();const newUsername=document.getElementById("newUsername").value;const newUserPassword=document.getElementById("newUserPassword").value;const newUserSuperAdmin=document.getElementById("newUserSuperAdmin").checked;if(newUsername.length<3){alert("Der Benutzername muss mindestens 3 Zeichen lang sein!");return}if(newUserPassword.length<4){alert("Das Passwort muss mindestens 4 Zeichen lang sein!");return}const success=await addUser(currentUser,newUsername,newUserPassword,newUserSuperAdmin);if(success){const statusText=newUserSuperAdmin?"Super Admin":"Admin";alert(`${statusText} "${newUsername}" erfolgreich hinzugefügt! Der Benutzer ist sofort auf allen Geräten verfügbar.`);addUserForm.reset();renderUsersList()}else{alert("Fehler beim Hinzufügen des Benutzers! Der Benutzername könnte bereits existieren.")}})}if(logoutBtn){logoutBtn.addEventListener("click",function(){localStorage.removeItem("currentAdminUser");alert("Du wurdest abgemeldet!");window.location.href="Untitled-1.html"})}const navToggle=document.querySelector(".nav-toggle");const nav=document.querySelector(".nav");if(navToggle){navToggle.addEventListener("click",function(){nav.classList.toggle("active")});nav.querySelectorAll("a").forEach(link=>{link.addEventListener("click",function(){nav.classList.remove("active")})})}const addSectionButton=document.getElementById("add-section");const sectionsList=document.getElementById("sections-list");if(addSectionButton){addSectionButton.addEventListener("click",()=>{const sectionName=prompt("Enter the name of the new section:");if(sectionName){const listItem=document.createElement("li");listItem.textContent=sectionName;listItem.contentEditable=true;sectionsList.appendChild(listItem);console.log(`Section "${sectionName}" added.`)}})}console.log("Loading sections...");const addMainMenuItemButton=document.getElementById("add-main-menu-item");addMainMenuItemButton.addEventListener("click",async()=>{const menuItemName=prompt("Enter the name of the new menu item:");if(menuItemName){try{const response=await fetch(`${API_URL}/create-menu-item`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:menuItemName})});if(response.ok){alert("Menu item added successfully!")}else{alert("Failed to add menu item.")}}catch(error){console.error("Error adding menu item:",error);alert("An error occurred while adding the menu item.")}}});const manageContentButton=document.getElementById("manage-content");const contentModal=document.getElementById("content-modal");const contentEditor=document.getElementById("content-editor");const saveContentButton=document.getElementById("save-content");const closeModalButton=document.getElementById("close-modal");manageContentButton.addEventListener("click",()=>{contentModal.style.display="block";contentEditor.value="Hier können Inhalte bearbeitet werden."});saveContentButton.addEventListener("click",async()=>{const updatedContent=contentEditor.value;try{const response=await fetch(`${API_URL}/update-content`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({content:updatedContent})});if(response.ok){alert("Inhalte erfolgreich gespeichert!");contentModal.style.display="none"}else{alert("Fehler beim Speichern der Inhalte.")}}catch(error){console.error("Fehler beim Speichern der Inhalte:",error);alert("Ein Fehler ist aufgetreten.")}});closeModalButton.addEventListener("click",()=>{contentModal.style.display="none"})});const API_URL="https://rp-world-backend.onrender.com/api";async function authenticateUser(username,password){try{const response=await fetch(`${API_URL}/login`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({username:username,password:password})});const data=await response.json();return data.success}catch(error){console.error("Authentifizierungsfehler:",error);return false}}async function getUserInfo(username){try{const response=await fetch(`${API_URL}/user/${username}`);const data=await response.json();if(data.success){return data.user}return null}catch(error){console.error("Fehler beim Abrufen der Benutzerinfo:",error);return null}}document.addEventListener("DOMContentLoaded",function(){const loginModal=document.getElementById("loginModal");const adminLoginBtn=document.getElementById("adminLoginBtn");const closeLoginModal=document.getElementById("closeLoginModal");const loginForm=document.getElementById("loginForm");const adminPanel=document.getElementById("adminPanel");const adminStatus=document.getElementById("adminStatus");const logoutBtn=document.getElementById("logoutBtn");const currentUser=localStorage.getItem("currentAdminUser");if(currentUser){adminPanel.style.display="block";adminStatus.textContent="✓ "+currentUser;if(adminLoginBtn)adminLoginBtn.style.display="none"}if(adminLoginBtn){adminLoginBtn.addEventListener("click",function(e){e.preventDefault();loginModal.classList.add("show")})}if(closeLoginModal){closeLoginModal.addEventListener("click",function(){loginModal.classList.remove("show");loginForm.reset()})}window.addEventListener("click",function(event){if(event.target===loginModal){loginModal.classList.remove("show");loginForm.reset()}});if(loginForm){loginForm.addEventListener("submit",async function(e){e.preventDefault();const username=document.getElementById("username").value;const password=document.getElementById("password").value;const isValid=await authenticateUser(username,password);if(isValid){localStorage.setItem("currentAdminUser",username);loginModal.classList.remove("show");loginForm.reset();window.location.href="admin.html"}else{alert("Benutzername oder Passwort ist falsch!");loginForm.reset()}})}if(logoutBtn){logoutBtn.addEventListener("click",function(){localStorage.removeItem("currentAdminUser");adminPanel.style.display="none";adminStatus.textContent="";if(adminLoginBtn)adminLoginBtn.style.display="block";alert("Sie wurden abgemeldet!")})}const navToggle=document.querySelector(".nav-toggle");const nav=document.querySelector(".nav");if(navToggle){navToggle.addEventListener("click",function(){nav.classList.toggle("active")});nav.querySelectorAll("a").forEach(link=>{link.addEventListener("click",function(){nav.classList.remove("active")})})}document.querySelectorAll('a[href^="#"]').forEach(anchor=>{anchor.addEventListener("click",function(e){const href=this.getAttribute("href");if(href!=="#"){e.preventDefault();const target=document.querySelector(href);if(target){target.scrollIntoView({behavior:"smooth"})}}})});const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.style.opacity="1"}})},{threshold:.1});document.querySelectorAll(".fade-in").forEach(elem=>{observer.observe(elem)})});